import os, re, json, hashlib, requests, yaml
from dotenv import dotenv_values
key = dotenv_values(".env").get("PFF_API_KEY","").strip()
B = "https://api.profootballfocus.com"; UA = {"User-Agent":"Mozilla/5.0"}
jwt = requests.post(B+"/auth/login", headers={**UA,"x-api-key":key}, timeout=30).json()["jwt"]
H = {**UA, "Authorization":"Bearer "+jwt}
out = os.environ["CLAUDE_JOB_DIR"]+"/tmp/pffspec"
slugs = ["bearer-auth","master-data","video-feeds","a22-feeds","diagrams","premium-feeds","translations-feeds",
         "stats-extended","player-tracking-feeds","grades-feeds","open-exchange-feeds","iq-feeds"]
PAT = re.compile(r"\bepa\b|_epa|epa_|expected.?points|points.?added|\bep\b|_ep\b|\bep_|\bppa\b", re.I)
for s in slugs:
    r = requests.get(f"{B}/doc/swagger/{s}.yaml", headers=H, timeout=60)
    if r.status_code != 200:
        print(f"{s}: HTTP {r.status_code}"); continue
    open(f"{out}/{s}.yaml","wb").write(r.content)
    saved = f"docs/swagger/{s}.yaml"
    same = "n/a"
    if os.path.exists(saved):
        same = "SAME" if hashlib.md5(open(saved,"rb").read()).digest()==hashlib.md5(r.content).digest() else "CHANGED"
    spec = yaml.safe_load(r.text)
    ver = (spec.get("info") or {}).get("version")
    npaths = len(spec.get("paths") or {})
    hits = set()
    def walk(n, path):
        if isinstance(n, dict):
            for k,v in n.items():
                if PAT.search(str(k)): hits.add(f"key {path}/{k}")
                if k in ("description","summary") and isinstance(v,str) and PAT.search(v): hits.add(f"desc {path}: {v[:90]}")
                walk(v, f"{path}/{k}")
        elif isinstance(n, list):
            for v in n: walk(v, path)
    walk(spec, "")
    for p in (spec.get("paths") or {}):
        if PAT.search(p): hits.add(f"path {p}")
    print(f"{s}: v{ver} paths={npaths} saved={same} epa_hits={len(hits)}")
    for h in sorted(hits)[:10]: print("   ", h[:160])
# nested fields in IQ win_probability
r = requests.get(B+"/v1/iq/ncaa/games/31098/win_probability", headers=H, timeout=60).json()["win_probability"]
for f in ("post_play","actual","optimal"):
    ks=set(); ex=None
    for row in r:
        v=row.get(f)
        if isinstance(v,dict): ks|=set(v); ex=ex or v
        elif v is not None and ex is None: ex=v
    print(f"{f}: nested keys={sorted(ks)} example={json.dumps(ex)[:200]}")
EOF

