    return None


def shape_premium(payload: Any, category: str, game_id: str) -> list[dict]:
    """Passthrough premium rows: keep keys + full JSON for later modeling."""
    rows = _first_list(payload, category)
    game_meta = payload.get("game", {}) if isinstance(payload, dict) else {}
    out = []
    for i, r in enumerate(rows):
        if not isinstance(r, dict):
            continue
        out.append({
            "game_id": str(r.get("game_id", game_id)),
            "category": category,
            "row_seq": i,
            "pff_player_id": _premium_player_id(r, category),
            "play_id": str(r.get("play_id")) if r.get("play_id") is not None else None,
            "season": r.get("season", game_meta.get("season")),
            "week": r.get("week", game_meta.get("week")),
            "raw_json": json.dumps(r, separators=(",", ":")),
        })
    return out

"""Tests for src/ingest/pff_client.py using a fake requests.Session (no network)."""

from __future__ import annotations

import time

import jwt as pyjwt
import pytest

from src.ingest import pff_client
from src.ingest.pff_client import PFFAuthError, PFFClient


def _make_jwt(ttl_seconds: int = 3600) -> str:
    return pyjwt.encode(
        {"exp": int(time.time()) + ttl_seconds, "iat": int(time.time())},
        "test-secret", algorithm="HS256",
    )


class FakeResp:
    def __init__(self, status, json_body=None, text=""):
        self.status_code = status
        self._json = json_body if json_body is not None else {}
        self.text = text

    def json(self):
        return self._json

    def raise_for_status(self):
        if self.status_code >= 400:
            raise RuntimeError(f"HTTP {self.status_code}")


class FakeSession:
    def __init__(self, get_script=None, ttl=3600):
        self.get_script = list(get_script or [])
        self.ttl = ttl
        self.post_calls = []
        self.get_calls = []
        self.auth_count = 0

    def post(self, url, headers=None, timeout=None):
        self.post_calls.append({"url": url, "headers": headers})
        self.auth_count += 1
        assert headers and headers.get("x-api-key") == "KEY"
        return FakeResp(200, {"jwt": _make_jwt(self.ttl)})

    def get(self, url, headers=None, params=None, timeout=None):
        self.get_calls.append({"url": url, "headers": headers, "params": params})
        status, body = self.get_script.pop(0)
        return FakeResp(status, body)


@pytest.fixture(autouse=True)
def _no_sleep(monkeypatch):
    monkeypatch.setattr(pff_client.time, "sleep", lambda *_: None)


def _client(session, **kw):
    return PFFClient(base_url="https://api.test", api_key="KEY", session=session, **kw)


def test_requires_credentials(monkeypatch):
    monkeypatch.delenv("PFF_BASE_URL", raising=False)
    monkeypatch.delenv("PFF_API_KEY", raising=False)
    with pytest.raises(PFFAuthError):
        PFFClient(base_url="", api_key="")


def test_get_authenticates_then_sends_bearer():
    sess = FakeSession(get_script=[(200, {"leagues": [{"id": 2}]})])
    c = _client(sess)
    out = c.get_leagues()
    assert out == {"leagues": [{"id": 2}]}
    assert sess.auth_count == 1
    assert sess.get_calls[0]["headers"]["Authorization"].startswith("Bearer ")


def test_token_is_reused_within_lifetime():
    sess = FakeSession(get_script=[(200, {"a": 1}), (200, {"b": 2})])
    c = _client(sess)
    c.get_leagues()
    c.get_teams(2024)
    assert sess.auth_count == 1   # second call reused the cached token


def test_token_refreshes_when_expired():
    # ttl below the refresh margin forces a re-auth on every call
    sess = FakeSession(get_script=[(200, {"a": 1}), (200, {"b": 2})],
                       ttl=pff_client.TOKEN_REFRESH_MARGIN_SECONDS - 1)
    c = _client(sess)
    c.get_leagues()
    c.get_teams(2024)
    assert sess.auth_count == 2


def test_401_triggers_single_reauth_then_succeeds():
    sess = FakeSession(get_script=[(401, {"errors": {"detail": "Unauthorized"}}),
                                   (200, {"ok": True})])
    c = _client(sess)
    assert c.get_leagues() == {"ok": True}
    assert sess.auth_count == 2   # initial + one re-auth


def test_429_backs_off_and_retries():
    sess = FakeSession(get_script=[(429, {"errors": {"detail": "Too many requests"}}),
                                   (200, {"ok": True})])
    c = _client(sess)
    assert c.get_leagues() == {"ok": True}
    assert len(sess.get_calls) == 2


def test_persistent_429_raises_after_max_attempts():
    sess = FakeSession(get_script=[(429, {})] * pff_client.MAX_REQUEST_ATTEMPTS)
    c = _client(sess)
    with pytest.raises(RuntimeError):
        c.get_leagues()


def test_resource_paths_use_league_slug():
    sess = FakeSession(get_script=[(200, {"game_grade": []})])
    c = _client(sess, league="ncaa")
    c.get_game_grade(26212)
    assert sess.get_calls[0]["url"] == "https://api.test/v1/grades/ncaa/games/26212/game_grade"


def test_season_team_game_grades_path_uses_league_and_season():
    sess = FakeSession(get_script=[(200, {"games": []})])
    c = _client(sess, league="ncaa")
    c.get_season_team_game_grades(2024)
    assert sess.get_calls[0]["url"] == "https://api.test/v1/grades/ncaa/2024/team_game_grades"

