"""PFF API HTTP client.

Auth flow (confirmed in docs/pff_api_notes.md):
  1. POST {base}/auth/login with header `x-api-key: <key>` -> {"jwt": "..."}
  2. Send `Authorization: Bearer <jwt>` on all resource calls
  3. JWT lasts 3600s; re-auth on expiry or on HTTP 401

Mirrors the resilience pattern of ForcePlate_DecisionSystem/src/ingest/vald_client.py:
in-memory token cache with proactive refresh, exponential backoff on 429/5xx, and a
single re-auth retry on 401.

All methods return parsed JSON (dict/list). Reshaping into DB rows happens in
src/shape/, never here.
"""

from __future__ import annotations

import os
import time
from typing import Any, Iterator

import jwt as pyjwt
import requests

MAX_REQUEST_ATTEMPTS = 5
RETRY_BACKOFF_SECONDS = 2
REQUEST_TIMEOUT_SECONDS = 60
TOKEN_REFRESH_MARGIN_SECONDS = 60
DEFAULT_LEAGUE = "ncaa"


class PFFAuthError(RuntimeError):
    """Raised when the API key cannot be exchanged for a token."""


class PFFClient:
    def __init__(
        self,
        base_url: str | None = None,
        api_key: str | None = None,
        league: str = DEFAULT_LEAGUE,
        session: requests.Session | None = None,
    ) -> None:
        self.base_url = (base_url or os.environ.get("PFF_BASE_URL", "")).rstrip("/")
        self.api_key = api_key or os.environ.get("PFF_API_KEY", "")
        self.league = league
        if not self.base_url or not self.api_key:
            raise PFFAuthError(
                "PFF_BASE_URL and PFF_API_KEY must be set (in .env or passed explicitly)."
            )
        self._session = session or requests.Session()
        self._token: str | None = None
        self._token_exp: float = 0.0  # unix seconds

    # ---- auth ---------------------------------------------------------------

    def _authenticate(self) -> None:
        url = f"{self.base_url}/auth/login"
        resp = self._session.post(
            url,
            headers={"x-api-key": self.api_key, "Accept": "application/json"},
            timeout=REQUEST_TIMEOUT_SECONDS,
        )
        if resp.status_code != 200:
            raise PFFAuthError(
                f"Auth failed ({resp.status_code}): {resp.text[:200]}"
            )
        token = resp.json().get("jwt")
        if not token:
            raise PFFAuthError("Auth response did not contain a 'jwt' field.")
        self._token = token
        try:
            claims = pyjwt.decode(token, options={"verify_signature": False})
            self._token_exp = float(claims.get("exp", time.time() + 3600))
        except Exception:
            # If decode fails, assume the documented 1-hour lifetime.
            self._token_exp = time.time() + 3600

    def _ensure_token(self) -> None:
        if self._token is None or time.time() >= (self._token_exp - TOKEN_REFRESH_MARGIN_SECONDS):
            self._authenticate()

    # ---- core request -------------------------------------------------------

    def _get(self, path: str, params: dict[str, Any] | None = None) -> Any:
        self._ensure_token()
        url = f"{self.base_url}{path}"
        last_error: str = ""
        reauthed = False
        for attempt in range(1, MAX_REQUEST_ATTEMPTS + 1):
            headers = {
                "Authorization": f"Bearer {self._token}",
                "Accept": "application/json",
                "Accept-Encoding": "gzip",
            }
            try:
                resp = self._session.get(
                    url, headers=headers, params=params, timeout=REQUEST_TIMEOUT_SECONDS
                )
            except requests.RequestException as e:
                last_error = f"network error: {e}"
                time.sleep(RETRY_BACKOFF_SECONDS * attempt)
                continue

            if resp.status_code == 200:
                return resp.json()
            if resp.status_code == 401 and not reauthed:
                # Token likely expired mid-run; re-auth once and retry immediately.
                reauthed = True
                self._authenticate()
                continue
            if resp.status_code == 429 or 500 <= resp.status_code < 600:
                last_error = f"{resp.status_code}: {resp.text[:150]}"
                time.sleep(RETRY_BACKOFF_SECONDS * attempt)
                continue
            # Non-retryable (404, 403, etc.)
            resp.raise_for_status()
            return resp.json()
        raise RuntimeError(f"GET {path} failed after {MAX_REQUEST_ATTEMPTS} attempts: {last_error}")

    # ---- master data --------------------------------------------------------

    def get_leagues(self) -> Any:
        return self._get("/v1/leagues")

    def get_teams(self, season: int) -> Any:
        """-> {leagues, teams, ...}; the team rows are under 'teams'."""
        return self._get(f"/v1/{self.league}/{season}/teams")

    def get_games(self, season: int) -> Any:
        """-> {leagues, teams, games, stadiums}."""
        return self._get(f"/v1/{self.league}/{season}/games")

    def get_team_members(self, franchise_id: str | int) -> Any:
        return self._get(f"/v1/{self.league}/franchises/{franchise_id}/team_members")

    def iter_players(self, page_size: int = 1000) -> Iterator[dict]:
        """Yield player rows across the paginated /players endpoint."""
        page = 1
        while True:
            payload = self._get(
                f"/v1/{self.league}/players",
                params={"page_number": page, "page_size": page_size},
            )
            rows = payload.get("players", []) if isinstance(payload, dict) else []
            for row in rows:
                yield row
            total_pages = payload.get("total_pages") if isinstance(payload, dict) else None
            if not rows or (total_pages is not None and page >= total_pages):
                break
            page += 1

    def get_game_status(self, season: int) -> Any:
        return self._get(f"/v1/{self.league}/game_status", params={"season": season})

    # ---- grades -------------------------------------------------------------

    def get_game_grade(self, game_id: str | int) -> Any:
        """-> {game_grade: [per-player rows]}."""
        return self._get(f"/v1/grades/{self.league}/games/{game_id}/game_grade")

    def get_team_game_grades(self, game_id: str | int) -> Any:
        return self._get(f"/v1/grades/{self.league}/games/{game_id}/team_game_grades")

    def get_season_team_game_grades(self, season: int) -> Any:
        return self._get(f"/v1/grades/{self.league}/{season}/team_game_grades")

    def get_season_grade(self, season: int) -> Any:
        return self._get(f"/v1/grades/{self.league}/{season}/season_grade")

    # ---- extended stats -----------------------------------------------------

    def get_extended_stats(self, season: int, category: str) -> Any:
        return self._get(f"/v1/stats/extended/{self.league}/{season}/{category}")

    # ---- premium ------------------------------------------------------------

    def get_premium_game(self, game_id: str | int, category: str) -> Any:
        return self._get(f"/v1/premium/{self.league}/games/{game_id}/{category}")

