                assert row["adjusted_sr"] is not None, (cut, row["season"])


def _built_report_inputs():
    """The real tables, if they have been built. Skipped rather than faked --
    a stub would let the renderer's prose drift from the numbers."""
    adjusted = pathlib.Path("outputs/tables/opponent_adjusted.csv")
    provenance = pathlib.Path("outputs/opponent_provenance.json")
    if not adjusted.exists() or not provenance.exists():
        pytest.skip("run build_opponent_tables.py first")
    tables = {"adjusted": pd.read_csv(adjusted)}
    for key, filename in (
        ("threshold", "opponent_success_threshold_by_band.csv"),
        ("declines", "opponent_success_definitions.csv"),
    ):
        path = pathlib.Path("outputs/tables") / filename
        if path.exists():
            tables[key] = pd.read_csv(path)
    return tables, json.loads(provenance.read_text())

