"""Tests for ingest orchestration using fake clients and in-memory DuckDB."""

from __future__ import annotations

import duckdb

from src import db
from src.ingest import pipeline


class FakeDimensionClient:
    def __init__(self):
        self.calls = []

    def get_teams(self, season):
        self.calls.append(("teams", season))
        return {"teams": [
            {"id": 118, "franchise_id": 118, "league": "NCAA", "abbreviation": "BAYLOR",
             "groups": [{"name": "Big 12"}]},
            {"id": 50, "franchise_id": 50, "league": "NCAA", "abbreviation": "OPP",
             "groups": [{"name": "Big 12"}]},
        ]}

    def get_games(self, season):
        self.calls.append(("games", season))
        return {"games": [
            {"id": 1, "season": season, "week": 1, "home_franchise_id": 118, "away_franchise_id": 50},
        ]}

    def get_season_team_game_grades(self, season):
        self.calls.append(("team_game_grades", season))
        return {"games": [
            {"id": 1, "home_team_score": 31, "away_team_score": 24},
        ]}


def test_ingest_dimensions_upserts_score_enriched_games():
    conn = duckdb.connect(":memory:")
    try:
        db.init_schema(conn)
        client = FakeDimensionClient()
        games = pipeline._ingest_dimensions_and_scope(
            conn,
            client,
            {"scope": {"baylor_franchise_id": "118", "conferences": ["Big 12"]}},
            2024,
        )
        assert games[0]["home_score"] == 31
        assert games[0]["away_score"] == 24
        assert ("team_game_grades", 2024) in client.calls
        row = conn.execute(
            "SELECT home_score, away_score FROM games WHERE game_id = '1'"
        ).fetchone()
        assert row == (31, 24)
    finally:
        conn.close()


class FakeResumeClient(FakeDimensionClient):
    def __init__(self):
        super().__init__()
        self.premium_calls = []

    def get_game_grade(self, game_id):
        raise AssertionError("resume mode should skip already-complete grades")

    def get_extended_stats(self, season, category):
        raise AssertionError("resume mode should skip already-complete stats")

    def get_premium_game(self, game_id, category):
        self.premium_calls.append((game_id, category))
        return {
            "game": {"season": 2023, "week": 1},
            category: [{"player_id": 7, "play_id": f"{category}-1", "game_id": game_id}],
        }


def test_run_one_season_resume_skips_complete_grades_and_stats_then_runs_premium():
    conn = duckdb.connect(":memory:")
    try:
        db.init_schema(conn)
        conn.execute(
            "INSERT INTO pff_grades "
            "(game_id, pff_player_id, grade_type, grade_value, season) "
            "VALUES ('1', '7', 'overall', 80.0, 2023)"
        )
        for category in pipeline.EXTENDED_CATEGORIES:
            conn.execute(
                "INSERT INTO pff_stats "
                "(game_id, pff_player_id, stat_category, stat_name, stat_value, season) "
                "VALUES ('1', '7', ?, 'sample', 1.0, 2023)",
                [category],
            )

        client = FakeResumeClient()
        summary = pipeline._run_one_season(
            conn,
            client,
            {
                "scope": {"baylor_franchise_id": "118", "conferences": ["Big 12"]},
                "fetch": {"endpoints": ["teams", "games", "grades", "stats", "premium"]},
            },
            2023,
            resume=True,
        )

        assert summary["grades"] == "skipped"
        assert summary["stats"] == "skipped"
        assert summary["premium"] == len(pipeline.PREMIUM_CATEGORIES)
        assert len(client.premium_calls) == len(pipeline.PREMIUM_CATEGORIES)
    finally:
        conn.close()


def test_premium_categories_include_play_level_feeds():
    """team_play, rushing and quarterback_charting are play-level feeds keyed by
    play_id. The play-call analysis needs all three: team_play is the master play
    list, rushing carries def_package for run plays, and quarterback_charting is
    the only source of per-play coverage."""
    from src.ingest.pipeline import PREMIUM_CATEGORIES

    for category in ("team_play", "rushing", "quarterback_charting"):
        assert category in PREMIUM_CATEGORIES


class FakeVideoClient:
    def __init__(self):
        self.calls = []

    def get_video_game_plays(self, game_id):
        self.calls.append(game_id)
        return {
            "game": {"season": 2024, "week": 1},
            "plays": [
                {"play_id": 11, "expected_points_added": 0.5},
                {"play_id": 12, "expected_points_added": -0.2},
            ],
        }


def test_ingest_video_plays_stores_rows_and_skips_games_already_pulled():
    conn = duckdb.connect(":memory:")
    try:
        db.init_schema(conn)
        client = FakeVideoClient()
        first = pipeline.ingest_video_plays(conn, client, [("26267", 2024, 1)])
        second = pipeline.ingest_video_plays(conn, client, [("26267", 2024, 1)])

        assert first == {"pulled": 1, "skipped": 0, "failed": 0, "rows": 2}
        assert second["skipped"] == 1
        assert client.calls == ["26267"]
        stored = conn.execute(
            "SELECT play_id, season FROM pff_premium WHERE category = 'video_plays' ORDER BY play_id"
        ).fetchall()
        assert stored == [("11", 2024), ("12", 2024)]
    finally:
        conn.close()


def test_video_plays_stay_out_of_the_season_loop():
    """In PREMIUM_CATEGORIES it would pull every scoped game on the next backfill."""
    assert pipeline.VIDEO_PLAYS_CATEGORY not in pipeline.PREMIUM_CATEGORIES

