"""Compare per-play EPA from three models on the same Baylor plays.

EPA (CFBD PPA) is the column Phase 2 attached. EPA (PFF current) and EPA (PFF
legacy) come from PFF's video plays feed, which PFF_Data_Project stores in
pff_premium as category `video_plays`. They are two different PFF models, not
two copies of one: on Baylor-Tarleton 2024 they matched on 2 of 208 plays. The
PFF website is believed to show the current model. That is the user's belief,
not verified against a play on Ultimate.

Agreement is not correctness. Two models can agree and both be wrong, so the
agreement tables say how much the choice of source moves a number, not which
source is right. The drive sums are the one place a right answer exists, and
only roughly. Which model PREDICTS better needs every FBS team, not 25 Baylor
games, and is not attempted here.

Pure functions. build_sources_tables.py does the reading and writing.
"""

from __future__ import annotations

import pandas as pd

from src.playcalls import analysis, opponent, pff

VIDEO_CATEGORY = "video_plays"

SOURCES = {
    "cfbd": "EPA (CFBD PPA)",
    "pff": "EPA (PFF current)",
    "pff_legacy": "EPA (PFF legacy)",
}
COLUMNS = {"cfbd": "epa_cfbd", "pff": "epa_pff", "pff_legacy": "epa_pff_legacy"}
PAIRS = (("cfbd", "pff"), ("cfbd", "pff_legacy"), ("pff", "pff_legacy"))

# The one-game probe attached every play. A miss means a bug, not a gap.
ATTACH_GATE = 0.99

MIN_SAMPLE = opponent.MIN_SAMPLE

# Drive sums are only checkable against theory for a fixed start. Drives from
# the own 20-30 are the band Phase 2 used to verify EPA (CFBD PPA).
THEORY_START_YARDS_TO_GOAL = (70, 80)
DRIVE_THEORY = {"TOUCHDOWN": 5.5, "FIELD GOAL": 1.8, "PUNT": -1.4}

BUCKET_COLUMNS = ("form_fam_norm", "personnel_family", "concept")

TAIL_COLUMNS = [
    "season", "game_code", "def_team", "quarter", "game_clock", "down",
    "distance", "yards_to_goal", "gain", "play_result", "cfbd_play_type",
    "field_zone", "garbage_time",
]


def load_pff_epa(game_ids, db_path: str = pff.PFF_DB_PATH) -> pd.DataFrame:
    """Baylor-offense PFF EPA for each game, one row per play_key."""
    frames = []
    for game_id in game_ids:
        rows = pff.load_category(str(game_id), VIDEO_CATEGORY, db_path)
        if rows.empty:
            raise ValueError(
                f"no {VIDEO_CATEGORY} rows for game {game_id}. Pull them in "
                "PFF_Data_Project:\n  python scripts/pull_video_plays.py "
                "--season YYYY"
            )
        rows = rows[rows["offense"] == pff.BAYLOR_CODE]
        frames.append(pd.DataFrame({
            "play_key": analysis._play_key(rows["play_id"]),
            "epa_pff": pd.to_numeric(rows["expected_points_added"], errors="coerce"),
            "epa_pff_legacy": pd.to_numeric(
                rows["expected_points_added_legacy"], errors="coerce"
            ),
            "ep_pff": pd.to_numeric(rows["expected_points"], errors="coerce"),
            "pff_no_play": pd.to_numeric(rows["no_play"], errors="coerce"),
            "pff_penalty": rows["penalty"] if "penalty" in rows else None,
        }))
    return pd.concat(frames, ignore_index=True).drop_duplicates("play_key")


def attach(joined: pd.DataFrame, pff_epa: pd.DataFrame) -> pd.DataFrame:
    """Add the three EPA columns to the joined play table, keyed on play_id."""
    frame = joined.copy()
    frame["play_key"] = analysis._play_key(frame["play_id"])
    frame["epa_cfbd"] = pd.to_numeric(frame["epa"], errors="coerce")
    merged = frame.merge(pff_epa, on="play_key", how="left", validate="m:1")
    # A charting row with no play_id has key "<NA>"; it must never attach.
    no_id = frame["play_id"].isna().to_numpy()
    merged.loc[no_id, ["epa_pff", "epa_pff_legacy", "ep_pff"]] = float("nan")
    return merged


def comparable_mask(frame: pd.DataFrame) -> pd.Series:
    """Plays every source scored, with penalty-wiped plays removed.

    CFBD carries no EPA for most penalty-wiped plays and PFF marks them with
    no_play. Comparing on them would compare a real number with a missing one.
    """
    scored = frame[list(COLUMNS.values())].notna().all(axis=1)
    live = frame["pff_no_play"].ne(1) & frame["cfbd_play_type"].ne("Penalty")
    return (scored & live).astype(bool)


def coverage(frame: pd.DataFrame) -> pd.DataFrame:
    """Per season: how many plays each source scored, and the attach rate."""
    rows = []
    ok = comparable_mask(frame)
    for season, part in frame.groupby("season"):
        with_id = part["play_id"].notna()
        attached = part["epa_pff"].notna() & with_id
        rows.append({
            "season": int(season),
            "plays": int(len(part)),
            "with_play_id": int(with_id.sum()),
            "pff_attached": int(attached.sum()),
            "attach_rate": round(float(attached.sum() / max(with_id.sum(), 1)), 4),
            "cfbd_scored": int(part["epa_cfbd"].notna().sum()),
            "pff_scored": int(part["epa_pff"].notna().sum()),
            "pff_no_play": int(part["pff_no_play"].eq(1).sum()),
            "cfbd_penalty_rows": int(part["cfbd_play_type"].eq("Penalty").sum()),
            "comparable": int(ok[part.index].sum()),
        })
    return pd.DataFrame(rows)


def pair_stats(frame: pd.DataFrame, a: str, b: str) -> dict:
    """How far apart two sources put the same plays."""
    x = frame[COLUMNS[a]].astype(float)
    y = frame[COLUMNS[b]].astype(float)
    out = {"source_a": SOURCES[a], "source_b": SOURCES[b], "plays": int(len(frame))}
    if len(frame) < MIN_SAMPLE:
        return {**out, "pearson": None, "spearman": None, "mean_diff": None,
                "mean_diff_se": None, "mean_abs_diff": None, "loa_low": None,
                "loa_high": None, "sign_disagree": None}
    diff = x - y
    spread = float(diff.std())
    se = (
        opponent.standard_error(frame.assign(_epa=diff), cluster_column="game_code")
        if "game_code" in frame else None
    )
    return {
        **out,
        "pearson": round(float(x.corr(y)), 4),
        "spearman": round(float(x.corr(y, method="spearman")), 4),
        "mean_diff": round(float(diff.mean()), 4),
        "mean_diff_se": se,
        "mean_abs_diff": round(float(diff.abs().mean()), 4),
        "loa_low": round(float(diff.mean()) - 1.96 * spread, 4),
        "loa_high": round(float(diff.mean()) + 1.96 * spread, 4),
        "sign_disagree": round(float(((x > 0) != (y > 0)).mean()), 4),
    }


def slice_labels(frame: pd.DataFrame) -> dict[str, pd.Series]:
    """The cuts agreement is split by. Play type always comes from CFBD."""
    play_type = frame["cfbd_play_type"]
    return {
        "season": frame["season"].astype(str),
        "run_pass": play_type.map(opponent.classify_run_pass),
        "down": frame["down"].astype(str),
        "field_zone": frame["field_zone"].fillna("unknown"),
        "garbage_time": frame["garbage_time"].map({True: "garbage", False: "competitive"}),
        "turnover": play_type.isin(
            opponent.TURNOVER_PLAY_TYPES | {"Fumble Recovery (Opponent)"}
        ).map({True: "turnover", False: "no turnover"}),
        "sack": play_type.eq("Sack").map({True: "sack", False: "not a sack"}),
        "touchdown": play_type.fillna("").str.contains("Touchdown").map(
            {True: "touchdown", False: "no touchdown"}
        ),
        "explosive": frame["explosive"].eq("Y").map(
            {True: "explosive", False: "not explosive"}
        ),
    }


def agreement_table(frame: pd.DataFrame) -> pd.DataFrame:
    """Every pair, overall and on every slice. Thin cells print plays only."""
    rows = [
        {"slice": "all", "value": "all", **pair_stats(frame, a, b)}
        for a, b in PAIRS
    ]
    for name, labels in slice_labels(frame).items():
        for value, part in frame.groupby(labels, dropna=False):
            for a, b in PAIRS:
                rows.append({"slice": name, "value": str(value),
                             **pair_stats(part, a, b)})
    return pd.DataFrame(rows)


def game_level(frame: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """EPA per play per game under each source, and how the games line up."""
    games = (
        frame.groupby(["season", "game_code", "def_team"])
        .agg(plays=("epa_cfbd", "size"),
             **{f"mean_{key}": (column, "mean") for key, column in COLUMNS.items()})
        .reset_index()
    )
    for key in COLUMNS:
        games[f"mean_{key}"] = games[f"mean_{key}"].round(4)
        games[f"rank_{key}"] = games[f"mean_{key}"].rank(ascending=False).astype(int)

    rows = []
    for a, b in PAIRS:
        x, y = games[f"mean_{a}"], games[f"mean_{b}"]
        rows.append({
            "source_a": SOURCES[a], "source_b": SOURCES[b],
            "games": int(len(games)),
            "pearson": round(float(x.corr(y)), 4),
            "spearman": round(float(x.corr(y, method="spearman")), 4),
            "mean_abs_diff": round(float((x - y).abs().mean()), 4),
            "max_abs_diff": round(float((x - y).abs().max()), 4),
            "max_rank_shift": int((games[f"rank_{a}"] - games[f"rank_{b}"]).abs().max()),
        })
    return games, pd.DataFrame(rows)


def disagreement_tail(frame: pd.DataFrame, n: int = 40) -> pd.DataFrame:
    """The plays where EPA (CFBD PPA) and EPA (PFF current) differ most."""
    out = frame.assign(
        diff_cfbd_minus_pff=(frame["epa_cfbd"] - frame["epa_pff"]).round(4)
    )
    out = out.reindex(out["diff_cfbd_minus_pff"].abs().sort_values(ascending=False).index)
    keep = [c for c in TAIL_COLUMNS if c in out.columns]
    return out[keep + list(COLUMNS.values()) + ["diff_cfbd_minus_pff"]].head(n)


def drive_sums(frame: pd.DataFrame) -> pd.DataFrame:
    """Mean summed EPA per drive, by how the drive ended, under each source.

    Only drives where every charted play is comparable. The charting file
    misses a few plays per season, so a sum is over charted plays, and a drive
    that lost a play to the join is dropped rather than summed short. The
    theory column applies to the own 20-30 start band only.
    """
    work = frame.assign(_ok=comparable_mask(frame))
    drives = (
        work.groupby(["season", "game_code", "drive"])
        .agg(drive_end=("drive_end", "first"),
             start_yards_to_goal=("yards_to_goal", "first"),
             plays=("_ok", "size"),
             complete=("_ok", "all"),
             **{f"sum_{key}": (column, "sum") for key, column in COLUMNS.items()})
        .reset_index()
    )
    drives = drives[drives["complete"]]
    low, high = THEORY_START_YARDS_TO_GOAL
    band = drives["start_yards_to_goal"].between(low, high)

    rows = []
    for scope, part in (("all complete drives", drives),
                        ("start own 20-30", drives[band])):
        for end, group in part.groupby("drive_end"):
            row = {"scope": scope, "drive_end": end, "drives": int(len(group))}
            for key in COLUMNS:
                row[f"mean_sum_{key}"] = (
                    round(float(group[f"sum_{key}"].mean()), 3)
                    if len(group) >= 5 else None
                )
            row["theory"] = DRIVE_THEORY.get(end) if scope == "start own 20-30" else None
            rows.append(row)
    return pd.DataFrame(rows)


CUTS = ("overall", "run", "pass", "early_down_run")


def _cut(frame: pd.DataFrame, cut: str) -> pd.DataFrame:
    kind = frame["cfbd_play_type"].map(opponent.classify_run_pass)
    if cut == "overall":
        return frame
    if cut in ("run", "pass"):
        return frame[(kind == cut).astype(bool)]
    return frame[((kind == "run") & frame["early_down"].astype(bool)).astype(bool)]


def season_means(frame: pd.DataFrame) -> pd.DataFrame:
    """Season EPA per play under each source, with game-clustered errors, and
    whether the 2024-to-2025 change points the same way."""
    seasons = sorted(int(s) for s in frame["season"].unique())
    rows = []
    for cut in CUTS:
        part = _cut(frame, cut)
        for key, column in COLUMNS.items():
            row = {"cut": cut, "source": SOURCES[key]}
            means, errors = {}, {}
            for season in seasons:
                season_part = part[part["season"] == season]
                means[season] = float(season_part[column].mean())
                errors[season] = opponent.standard_error(
                    season_part.assign(_epa=season_part[column]),
                    cluster_column="game_code",
                )
                row[f"plays_{season}"] = int(len(season_part))
                row[f"epa_{season}"] = round(means[season], 4)
                row[f"se_{season}"] = errors[season]
            if len(seasons) >= 2:
                first, last = seasons[0], seasons[-1]
                row["change"] = round(means[last] - means[first], 4)
                if errors[first] is not None and errors[last] is not None:
                    row["change_se"] = round(
                        (errors[first] ** 2 + errors[last] ** 2) ** 0.5, 4
                    )
            rows.append(row)
    return pd.DataFrame(rows)


def bucket_ranks(frame: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Does the source change which buckets look best and worst?

    The EPA-driven tendency method ranks buckets by EPA per play. If the three
    sources rank them differently, the source is a decision, not a detail.
    """
    detail, summary = [], []
    for column in BUCKET_COLUMNS:
        if column not in frame.columns:
            continue
        for season, part in frame.groupby("season"):
            grouped = (
                part.dropna(subset=[column])
                .groupby(column)
                .agg(plays=("epa_cfbd", "size"),
                     **{f"mean_{k}": (c, "mean") for k, c in COLUMNS.items()})
                .reset_index()
            )
            grouped = grouped[grouped["plays"] >= MIN_SAMPLE].copy()
            if len(grouped) < 4:
                continue
            for key in COLUMNS:
                grouped[f"mean_{key}"] = grouped[f"mean_{key}"].round(4)
                grouped[f"rank_{key}"] = (
                    grouped[f"mean_{key}"].rank(ascending=False, method="min").astype(int)
                )
            detail.append(grouped.rename(columns={column: "bucket"}).assign(
                season=int(season), column=column
            ))
            for a, b in PAIRS:
                top = lambda k: set(grouped.nsmallest(3, f"rank_{k}")["bucket" if False else column])
                bottom = lambda k: set(grouped.nlargest(3, f"rank_{k}")[column])
                summary.append({
                    "season": int(season), "column": column,
                    "source_a": SOURCES[a], "source_b": SOURCES[b],
                    "buckets": int(len(grouped)),
                    "spearman": round(float(
                        grouped[f"mean_{a}"].corr(grouped[f"mean_{b}"], method="spearman")
                    ), 4),
                    "max_rank_shift": int(
                        (grouped[f"rank_{a}"] - grouped[f"rank_{b}"]).abs().max()
                    ),
                    "same_top_3": top(a) == top(b),
                    "same_bottom_3": bottom(a) == bottom(b),
                })
    detail_frame = pd.concat(detail, ignore_index=True) if detail else pd.DataFrame()
    return detail_frame, pd.DataFrame(summary)

