    "cfbd": "EPA (CFBD PPA)",
    "pff": "EPA (PFF current)",
    "pff_legacy": "EPA (PFF legacy)",
}
COLUMNS = {"cfbd": "epa_cfbd", "pff": "epa_pff", "pff_legacy": "epa_pff_legacy"}
PAIRS = (("cfbd", "pff"), ("cfbd", "pff_legacy"), ("pff", "pff_legacy"))

