def _turnover_kind(rows: pd.DataFrame) -> pd.Series:
    """PFF's call on whether the offence gave the ball away, and how.

    PFF omits zero-valued fields, so a column can be missing outright when no
    row in the game had one.
    """
    def column(name: str) -> pd.Series:
        if name in rows:
            return rows[name]
        return pd.Series([None] * len(rows), index=rows.index, dtype=object)

    turnover = pd.to_numeric(column("turnover"), errors="coerce").eq(1)
    kind = pd.Series("none", index=rows.index, dtype=object)
    kind.loc[turnover] = "other turnover"
    kind.loc[turnover & column("fumble").notna()] = "fumble lost"
    kind.loc[turnover & column("interception").notna()] = "interception"
    return kind


