def turnover_labels(frame: pd.DataFrame) -> pd.DataFrame:
    """Plays where PFF or CFBD calls a giveaway, cross-tabbed.

    The largest EPA gaps between the sources are labelling, not modelling:
    CFBD's play-by-play tags some lost fumbles as "Fumble Recovery (Own)", a
    reception or a sack, and its EPA then scores the yards rather than the
    giveaway. On those plays PFF names the defender who recovered and the
    Baylor chart's drive_end reads FUMBLE.
    """
    work = frame.assign(
        cfbd_says=frame["cfbd_play_type"].isin(CFBD_GIVEAWAY_TYPES).map(
            {True: "turnover", False: "no turnover"}
        ),
        pff_turnover_kind=frame["pff_turnover_kind"].fillna("none"),
    )
    work = work[work["pff_turnover_kind"].ne("none") | work["cfbd_says"].eq("turnover")]
    table = (
        work.groupby(["pff_turnover_kind", "cfbd_says", "cfbd_play_type"])
        .agg(plays=("epa_cfbd", "size"),
             **{f"mean_{key}": (column, "mean") for key, column in COLUMNS.items()})
        .reset_index()
    )
    for key in COLUMNS:
        table[f"mean_{key}"] = table[f"mean_{key}"].round(3)
    return table.sort_values(["pff_turnover_kind", "cfbd_says", "plays"],
                             ascending=[True, True, False])


