def pff_zeros(frame: pd.DataFrame) -> pd.DataFrame:
    """Plays each source scores as exactly zero.

    PFF zeroes plays that run out a half or the game, kneels included: with the
    half over, no points are at stake. CFBD scores the same kneel as a loss of
    around a point. Counted here so the difference is visible, not filtered.
    """
    seconds = pd.to_numeric(frame["game_clock"].map(_clock_seconds), errors="coerce")
    final_minute = (
        (frame["quarter"].isin([2, 4]) & seconds.le(60)) | frame["quarter"].ge(5)
    ).astype(bool)
    kneel = frame["run_pass"].eq("X").astype(bool)
    rows = []
    for key, column in COLUMNS.items():
        zero = frame[column].eq(0).astype(bool)
        rows.append({
            "source": SOURCES[key],
            "plays": int(len(frame)),
            "exact_zero": int(zero.sum()),
            "zero_in_final_minute_or_overtime": int((zero & final_minute).sum()),
            "zero_kneels": int((zero & kneel).sum()),
            "kneels": int(kneel.sum()),
            "mean_cfbd_on_zero_plays": (
                round(float(frame.loc[zero, "epa_cfbd"].mean()), 3) if zero.any() else None
            ),
        })
    return pd.DataFrame(rows)


